// Collapses the suppression list and today's send count into one item, and stops the run when the shared daily cap is reached.
const DAILY_CAP_TOTAL = 10; // first touches + follow-ups combined, one Gmail account
const supp = $('Fetch Suppression List').all().map(i => i.json).filter(j => j && j.id);
const domains = new Set();
for (const r of supp) {
  const f = r.fields || r;
  const d = String(f.Domain || '').toLowerCase().trim();
  if (d) domains.add(d);
}
const sendsToday = $input.all().filter(i => i.json && i.json.id).length;
if (sendsToday >= DAILY_CAP_TOTAL) return []; // shared cap reached: nothing sends this cycle
return [{ json: { suppressed_domains: [...domains], sends_today_total: sendsToday, daily_cap_total: DAILY_CAP_TOTAL } }];
